use crate::aap::caps::response_channel;

struct Node;

/// Precondition from the node contract: len(text) <= 100000, counted in
/// code points to match the Python-side `len`.
const MAX_TEXT_CHARS: usize = 100_000;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        assert!(
            reply.text.chars().count() <= MAX_TEXT_CHARS,
            "SendReply precondition violated: len(text) > 100000"
        );

        let confirmation = response_channel::send(&reply.text);

        // Postconditions: delivered == true and present(session_id).
        // The guest cannot repair a violated postcondition, so it traps
        // rather than returning a confirmation that claims a delivery
        // that did not happen or names no session.
        assert!(
            confirmation.delivered,
            "SendReply postcondition violated: delivered == false"
        );
        assert!(
            !confirmation.session.is_empty(),
            "SendReply postcondition violated: session_id not present"
        );

        confirmation
    }
}

export!(Node);
